"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";

export function TextMorphPrimitive({ value }: { value: string }) {
  const reduceMotion = useReducedMotion();
  return (
    <AnimatePresence mode="wait" initial={false}>
      <motion.span
        key={value}
        initial={reduceMotion ? false : { opacity: 0, filter: "blur(8px)", y: 5 }}
        animate={{ opacity: 1, filter: "blur(0px)", y: 0 }}
        exit={reduceMotion ? { opacity: 0 } : { opacity: 0, filter: "blur(8px)", y: -5 }}
        transition={reduceMotion ? { duration: 0.12 } : { duration: 0.24, delay: 0.12, ease: [0.23, 1, 0.32, 1] }}
      >
        {value}
      </motion.span>
    </AnimatePresence>
  );
}
